["Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes."]="將電動采集模塊和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。",
["Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."]="給荒蕪之地的裏格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。",
["Bring Ambassador Malcin's Head to Varimathras in the Undercity."]="把瑪克林大使的頭顱交給幽暗城的瓦裏瑪薩斯。",
["Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."]="把死亡騎士達克雷爾的徽記交給奧格瑞瑪智慧谷的薩格尼。",
["Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes."]="將末日扣環交給燃燒平原的瑪亞拉·布萊特文。",
["Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind."]="將工頭希斯耐特的探險者協會徽章交給暴風城的維爾德·薊草。",
["Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas."]="把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。",
["Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas."]="把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。",
