["Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus."]="將專註聖典、1塊原始黑鉆石、4份大塊魔光碎片和2張暗影之皮交給厄運之槌的博學者萊德羅斯，以換取壹份專註秘藥。",
["Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection."]="將防護聖典、1塊原始黑鉆石、2份大塊魔光碎片和1份磨損的憎惡縫合線交給厄運之槌的博學者萊德羅斯，以換取壹份防護秘藥。",
["Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity."]="將急速聖典、1塊原始黑鉆石、2份大塊魔光碎片和2份英雄之血交給厄運之槌的博學者萊德羅斯，以換取壹份急速秘藥。",
["Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge."]="將彩色穿孔卡片交給鐵爐堡的大機械師卡斯派普。",
