["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."]="在通靈學院裏找到萊斯·霜語。當妳找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果妳成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。",
["Find Starfall in Winterspring and speak with Wynd Nightchaser."]="找到冬泉谷的墜星村，在那裏與維恩德·夜風談壹談。",
["Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."]="找到《亡靈的起源》，把它交給幽暗城的帕科瓦·芬塔拉斯。",
["Find a clue as to the gems' whereabouts in the depths of Uldaman."]="在奧達曼裏找尋寶石的線索。",
["Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus."]="將塔莎拉的墜飾帶給達納蘇斯的塔莎拉·靜水。",
["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."]="找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。妳還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。",
["Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane."]="在斯坦索姆找到黑衣守衛鑄劍師，然後殺死他。將黑色衛士徽記交給亡靈殺手瑟裏爾。",
["Find the Deathstalker Adamant and Deathstalker Vincent."]="找到亡靈哨兵阿達曼特和亡靈哨兵文森特。",
["Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."]="在厄運之槌中找到魔藤，然後從它上面采集壹塊碎片。只有幹掉了奧茲恩之後，妳才能進行采集工作。使用凈化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。",
