["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."]="殺掉20只瘟疫龍崽，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。",
["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."]="殺掉6個達拉然召喚師和12個元素奴仆，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。",
["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."]="殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌復命。",
["Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher."]="殺死阿魯高，把他的頭帶給瑟伯切爾的達拉爾·道恩維沃爾。",
["Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade."]="殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。",
["Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar."]="殺死巴紮蘭和祈求者耶戈什，然後回到奧格瑞瑪的薩爾那裏。",
["Kill Edwin VanCleef and bring his head to Gryan Stoutmantle."]="殺死艾德溫·範克裏夫，把他的頭交給格裏安·斯托曼。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."]="殺死大檢察官懷特邁恩，血色十字軍指揮官莫格萊尼，十字軍的勇士赫洛德和馴犬者洛克希並向南海鎮的萊雷恩復命。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."]="殺掉大檢察官懷特邁恩、血色十字軍指揮官莫格萊尼、血色十字軍勇士赫洛德和馴犬者洛克希，然後向幽暗城的瓦裏瑪薩斯回報。",
["Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale."]="殺掉黑暗深淵裏的洛古斯·傑特，然後向灰谷的耶努薩克雷復命。",
