["Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."]="到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯復命。",
["Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."]="到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裏。",
["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."]="到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。",
["Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."]="到黑石塔去摧毀那裏的座狼源頭。當妳離開的時候，赫林迪斯喊出了壹個名字：哈雷肯。這個詞就是獸人語中“座狼”的意思。",
["Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."]="到黑石塔去找到血斧座狼幼崽。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的座狼幼崽交給基布雷爾。",
["Travel to Blackrock Spire and find out what happened to Bijou."]="到黑石塔去查明比修的下落。",
["Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."]="到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。",
["Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."]="去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。",
["Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."]="到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。",
["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."]="把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。",
["Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived."]="前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥妳已經到達了。",
["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."]="在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒毀血色十字軍檔案。",
["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."]="到斯坦索姆城裏去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。",
["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."]="到斯坦索姆去，殺掉吞咽者拉姆斯登。把他的頭顱交給納薩諾斯。",
["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."]="到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當妳找到足夠的聖水之後就回去向萊尼德·巴薩羅梅復命。",
["Travel to Winterspring and find Haleh. Give her Awbee's scale."]="到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。",
["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."]="到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。",
